BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f9000000-0000-4000-8000-000000000001','push-admin@example.test','test-only','admin',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f9000000-0000-4000-8000-000000000002','f9000000-0000-4000-8000-000000000001',repeat('1',64));
DO $$ DECLARE actor uuid:='f9000000-0000-4000-8000-000000000001';sid uuid:='f9000000-0000-4000-8000-000000000002';e uuid;r uuid;v jsonb;s uuid;registered uuid;j public.delivery_jobs;hash text;BEGIN
 IF has_table_privilege('anon','public.push_subscriptions','SELECT') OR has_function_privilege('authenticated','public.advance_event_push()','EXECUTE') THEN RAISE EXCEPTION 'Browser push storage/RPC';END IF;
 v:=public.mutate_event(actor,NULL,'create',NULL,jsonb_build_object('title','Fictional push event','slug','fictional-push-event','description','Fictional test only','start_at',now()+interval '2 days','location','Fixture'),gen_random_uuid());e:=(v->>'id')::uuid;
 PERFORM public.mutate_event(actor,e,'publish',1,'{}',gen_random_uuid());
 PERFORM public.register_event_atomic('fictional-push-event','Fictional attendee','push-attendee@example.test',NULL,true,repeat('2',64),repeat('3',64));SELECT id INTO r FROM public.event_attendance WHERE event_id=e;
 hash:=encode(sha256(convert_to('push-attendee@example.test','UTF8')),'hex');
 PERFORM public.request_event_push_verification('fictional-push-event',repeat('a',64),repeat('b',64),'v1.fixture');
 IF EXISTS(SELECT 1 FROM public.event_push_verifications) THEN RAISE EXCEPTION 'Arbitrary unregistered address mailed';END IF;
 PERFORM public.request_event_push_verification('fictional-push-event',hash,repeat('b',64),'v1.fixture');
 v:=public.inspect_event_push_verification(repeat('b',64));IF(v->>'eventId')::uuid<>e OR v::text LIKE '%@%' THEN RAISE EXCEPTION 'Verified event scope';END IF;
 BEGIN PERFORM public.mutate_push_subscription(NULL,NULL,repeat('c',64),e,repeat('d',64),repeat('e',64),'v1.fixture','subscribe',gen_random_uuid());RAISE EXCEPTION 'Forged registration ownership';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'PUSH_VERIFICATION_REQUIRED' THEN RAISE;END IF;END;
 BEGIN PERFORM public.mutate_push_subscription(actor,gen_random_uuid(),NULL,e,repeat('d',64),repeat('e',64),'v1.fixture','subscribe',gen_random_uuid());RAISE EXCEPTION 'Forged admin session';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 v:=public.mutate_push_subscription(actor,sid,NULL,e,repeat('d',64),repeat('e',64),'v1.fixture','subscribe',gen_random_uuid());s:=(v->>'id')::uuid;
 v:=public.mutate_push_subscription(NULL,NULL,repeat('b',64),e,repeat('f',64),repeat('a',64),'v1.fixture','subscribe',gen_random_uuid());registered:=(v->>'id')::uuid;
 IF NOT gdg_security.push_owner_current(registered) THEN RAISE EXCEPTION 'Verified subscription owner missing';END IF;
 BEGIN PERFORM public.mutate_push_subscription(NULL,NULL,repeat('b',64),e,repeat('d',64),repeat('e',64),'v1.fixture','subscribe',gen_random_uuid());RAISE EXCEPTION 'Silently rebound device identity';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'PUSH_DEVICE_BOUND' THEN RAISE;END IF;END;
 v:=public.mutate_push_subscription(NULL,NULL,NULL,e,repeat('f',64),repeat('9',64),NULL,'unsubscribe',gen_random_uuid());
 IF(v->>'subscribed')::boolean OR(SELECT revoked_at FROM public.push_subscriptions WHERE id=registered) IS NOT NULL THEN RAISE EXCEPTION 'Guessed device secret revokes reminder';END IF;
 UPDATE public.event_attendance SET attendee_email='changed-push@example.test' WHERE id=r;
 IF gdg_security.push_owner_current(registered) THEN RAISE EXCEPTION 'Replaced registration identity inherits push';END IF;
 BEGIN PERFORM public.inspect_event_push_verification(repeat('b',64));RAISE EXCEPTION 'Old verified address reusable';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'PUSH_VERIFICATION_REQUIRED' THEN RAISE;END IF;END;
 UPDATE public.event_attendance SET attendee_email='push-attendee@example.test' WHERE id=r;
 v:=public.advance_event_push();IF(v->>'queued')::integer<>0 THEN RAISE EXCEPTION 'Reminder sent more than 24h early';END IF;
 UPDATE public.events SET start_at=now()+interval '23 hours 59 minutes' WHERE id=e;
 v:=public.advance_event_push();IF(v->>'queued')::integer<>2 THEN RAISE EXCEPTION 'Due reminder not queued';END IF;
 v:=public.advance_event_push();IF(v->>'queued')::integer<>0 THEN RAISE EXCEPTION 'Duplicate reminder occurrence';END IF;
 FOR j IN SELECT * FROM public.claim_worker_jobs(100,ARRAY['event_push_reminder']) LOOP
  IF public.prepare_event_push(j.id,gen_random_uuid()) IS NOT NULL OR public.finish_event_push(j.id,gen_random_uuid(),'accepted',201) THEN RAISE EXCEPTION 'Unfenced push';END IF;
  v:=public.prepare_event_push(j.id,j.lease_token);
  IF v->>'slug'<>'fictional-push-event' OR v::text LIKE '%@%' OR v->>'encrypted'<>'v1.fixture' THEN RAISE EXCEPTION 'Push payload scope';END IF;
  IF(SELECT subscription_id FROM public.push_delivery_log WHERE id=(j.payload->>'deliveryId')::uuid)=registered THEN
   IF NOT public.finish_event_push(j.id,j.lease_token,'expired',410) THEN RAISE EXCEPTION 'Push finish';END IF;
  ELSE PERFORM public.finish_event_push(j.id,j.lease_token,'accepted',201);END IF;
 END LOOP;
 IF(SELECT endpoint_encrypted FROM public.push_subscriptions WHERE id=registered) IS NOT NULL OR(SELECT revoked_at FROM public.push_subscriptions WHERE id=registered) IS NULL THEN RAISE EXCEPTION 'Expired endpoint not disabled/erased';END IF;
 IF(SELECT count(*) FROM public.push_delivery_log WHERE state='accepted')<>1 THEN RAISE EXCEPTION 'False provider acceptance';END IF;
 UPDATE public.events SET start_at=start_at-interval '1 minute' WHERE id=e;PERFORM public.advance_event_push();
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['event_push_reminder']);
 PERFORM public.finish_event_push(j.id,j.lease_token,'retry',503);
 IF(SELECT state FROM public.delivery_jobs WHERE id=j.id)<>'pending' OR(SELECT next_attempt_at FROM public.delivery_jobs WHERE id=j.id)<=now() THEN RAISE EXCEPTION 'Unbounded immediate push retry';END IF;
 UPDATE public.admin_users SET is_active=false WHERE id=actor;
 IF gdg_security.push_owner_current(s) THEN RAISE EXCEPTION 'Revoked account retains push';END IF;
 PERFORM public.cleanup_event_push();IF(SELECT endpoint_encrypted FROM public.push_subscriptions WHERE id=s) IS NOT NULL THEN RAISE EXCEPTION 'Revoked owner endpoint not erased';END IF;
 v:=public.begin_scheduled_job('event-push',gen_random_uuid());IF v->>'runId' IS NULL THEN RAISE EXCEPTION 'Push scheduler missing';END IF;
END $$;
ROLLBACK;
